<script setup lang="ts">
import {useRoute} from 'vue-router'
const route=useRoute()
const appLink=(web:string,mobile:string)=>route.path.startsWith('/admin-app/')?mobile:web
import {onBeforeUnmount,onMounted,ref} from 'vue'
import BackendLayout from '../components/BackendLayout.vue'
import LiveMap from './c-live-map.vue'
import {backend} from '../services/backend'
import {valueLabels} from '../data/backendResources'
const summary=ref<Record<string,number>|null>(null),events=ref<any[]>([]),margins=ref<any[]>([]),error=ref(''),loading=ref(false),controller=new AbortController()
async function load(){if(loading.value)return;loading.value=true;error.value='';const results=await Promise.allSettled([backend('/api/dashboard/facility-kpi',{signal:controller.signal}),backend('/api/dashboard/timeline?limit=12',{signal:controller.signal}),backend('/api/dashboard/risk-margin?limit=5',{signal:controller.signal})]);if(controller.signal.aborted)return;results.forEach((result,index)=>{if(result.status==='fulfilled'){if(index===0)summary.value=result.value;else if(index===1)events.value=result.value;else margins.value=result.value}else error.value=result.reason.message});loading.value=false}
onMounted(load);onBeforeUnmount(()=>controller.abort())
</script>
<template><BackendLayout><section class="service-workspace server-dashboard"><div class="service-heading"><h1>종합 현황</h1><button :disabled="loading" @click="load">새로고침</button></div><p v-if="error" class="service-error" role="alert">{{error}}</p><section class="server-summary"><div v-for="[key,label] in [['facilityCount','담당 시설'],['blockedCount','통제 중'],['dangerLevelCount','위험'],['pendingReviewCount','판별 대기'],['remainingCount','잔류 차량'],['alertsToday','오늘 알림']]" :key="key"><small>{{label}}</small><strong>{{summary?.[key!]??'—'}}</strong></div></section><div class="server-main"><section class="server-events"><h2>최근 이벤트</h2><RouterLink :to="appLink('/admin-reports?report=timeline','/admin-app/screen-13')">전체 보기 →</RouterLink><p v-if="!events.length">표시할 이벤트가 없습니다.</p><ol><li v-for="(event,index) in events" :key="index"><small>{{String(event.createdAt||'').replace('T',' ')}}</small><b>{{event.underpassName}}</b><span>{{valueLabels[event.riskLevel]||event.riskLevel}} · {{event.reason||event.eventType}}</span></li></ol></section><section class="server-map"><LiveMap :manager="true"/></section></div><section class="server-bottom"><div><h2>위험 임박 시설</h2><p v-if="!margins.length">표시할 시설이 없습니다.</p><ol><li v-for="facility in margins" :key="facility.underpassId">{{facility.underpassName}} · {{facility.riskScore}}점 · 임계치까지 {{facility.margin}}점</li></ol></div><nav><h2>주요 업무</h2><RouterLink :to="appLink('/admin-data/reviews','/admin-app/screen-4')">번호판 판별 →</RouterLink><RouterLink :to="appLink('/admin-data/transits','/admin-app/screen-5')">잔류 차량 확인 →</RouterLink><RouterLink :to="appLink('/admin-data/facilities','/admin-app/screen-4')">시설 통제·해제 →</RouterLink><RouterLink :to="appLink('/admin-reports','/admin-app/history')">통계·위험도 추이 →</RouterLink></nav></section></section></BackendLayout></template>
<style>.server-summary{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:16px;padding:20px;border:1px solid var(--line);border-radius:8px;margin-bottom:16px}.server-summary strong{display:block;font-size:26px}.server-main{display:grid;grid-template-columns:var(--admin-sidebar-width,380px) minmax(0,1fr);gap:16px}.server-events{border:1px solid var(--line);border-radius:8px;padding:16px;max-height:900px;overflow:auto}.server-events h2,.server-bottom h2{font-size:18px;margin:0 0 12px}.server-events ol{list-style:none;padding:0}.server-events li{display:flex;flex-direction:column;gap:6px;padding:14px 0;border-bottom:1px solid var(--line)}.server-map{min-width:0;border:1px solid var(--line);border-radius:8px;padding:16px}.server-map .page-c-live-map{padding:0;min-height:0}.server-map .page-c-live-map>h1{font-size:18px}.server-map .page-c-live-map .map-columns{grid-template-columns:minmax(0,1fr) 300px;gap:16px}.server-bottom{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:16px}.server-bottom>div,.server-bottom>nav{border:1px solid var(--line);border-radius:8px;padding:20px}.server-bottom nav{display:flex;flex-direction:column;gap:12px}@media(max-width:1200px){.server-main{grid-template-columns:1fr}.server-events{max-height:300px}.server-map .page-c-live-map .map-columns{grid-template-columns:1fr}}@media(max-width:600px){.server-summary{grid-template-columns:repeat(3,minmax(0,1fr));padding:12px;gap:12px}.server-bottom{grid-template-columns:1fr}.server-map{padding:10px}}</style>
